## Building Hangman

### Game State

```xiom
type Game {
  word: Str;
  guessed_letters: Vec[Char];
  lives: Int;
  display: Str;
}
```

### Initializing the Display

```xiom
fn create_display(word: Str) -> Str {
  let mut display = "";
  let mut i = 0;
  while i < word.len() {
    display = string.str_concat(display, "_");
    i += 1;
  };
  display
}
```

### Making a Guess

```xiom
fn make_guess(game: &mut Game, letter: Char) -> Bool {
  if already_guessed(game, letter) {
    io.println("Already guessed!");
    return false;
  };

  game.guessed_letters.push(letter);

  if word_contains(game.word, letter) {
    update_display(game, letter);
    return true;
  };

  game.lives -= 1;
  false
}

fn word_contains(word: Str, letter: Char) -> Bool {
  let mut i = 0;
  while i < word.len() {
    if word.get(i).unwrap() == letter { return true; };
    i += 1;
  };
  false
}

fn update_display(game: &mut Game, letter: Char) {
  let mut new_display = "";
  let mut i = 0;
  while i < game.word.len() {
    if game.word.get(i).unwrap() == letter {
      new_display = string.str_concat(new_display, string.from_char(letter));
    } else {
      new_display = string.str_concat(new_display, string.from_char(game.display.get(i).unwrap()));
    };
    i += 1;
  };
  game.display = new_display;
}
```

