type HangmanGame {
  word: Str;
  guessed: Vec[Char];
  lives: Int;
  display: Str;
}

fn has_won(game: &HangmanGame) -> Bool {
  let mut i = 0;
  while i < game.display.len() {
    if game.display.get(i).unwrap() == '_' { return false; };
    i += 1;
  };
  true
}

fn has_lost(game: &HangmanGame) -> Bool {
  game.lives <= 0
}

fn main() -> Int {
  let mut game = HangmanGame{
    word: "PYTHON",
    guessed: Vec[Char].new(),
    lives: 6,
    display: "______"
  };
  io.println(game.display);
  io.println(has_won(&game));
  io.println(has_lost(&game));
  return 0;
}
